mapper.select:
select name, sector_code as sectorCode
from municipality_street
where municipality_id = #{municipalityId}
  and replace(fold_text(name), '-', ' ') like '%' || replace(fold_text(#{query}), '-', ' ') || '%'
order by replace(fold_text(name), '-', ' ') like replace(fold_text(#{query}), '-', ' ') || '%' desc, name
limit #{limit}
